-- warehouse_camskin.lua : camera skin colliders for the Warehouse map (notes/match_place_flow.md, "Spawn camera"), 2026-10-16.
-- The Warehouse's visual wall meshes stand 0.15-1.6 studs proud of its collision walls (COLP_Wall_*). The third-person camera's
-- probe only sees queryable parts and stops 0.45 studs before a collision wall, so wherever the visual wall is further out
-- the camera ends up behind the visible surface (measured at the 2v2/3v3 teammate spawn slots by the east / west walls).
-- This adds invisible Parts flush with the visual wall faces (CanCollide + CanQuery + CanTouch, cloned from COLP_Wall_W:
-- Transparency 1, no shadow), so the camera and the characters stop where the wall is drawn. Data: fix/data/warehouse_camskin.json
-- (generated by tools/camskin_gen.lua from the visual meshes' real triangles), embedded below by tools/camskin_build.py.
-- Where: the map model's own folder Warehouse.CamSkin (not CollisionProxies: smoke / blast rays and the bots' cover spots keep
-- reading only the original proxies).
--   Match place (331cb3a0): Workspace.Warehouse.CamSkin
--   Lobby (8ef4e21a): ServerStorage._DuelSource.Warehouse.Warehouse.CamSkin, then re-run fix/duel_split_map.lua so the arena's
--   Solid layer gets them (every part that collides is copied into Solid; the Visual layer never shows them).
-- Idempotent (the folder is rebuilt from the data). UNDO removes the folder (then re-run duel_split_map.lua in the lobby).
local UNDO = false --@UNDO
local HS = game:GetService("HttpService")
local DATA = [==[[{"proud": 0.7, "size": [0.8999999761581421, 12, 14], "name": "COLP_CamSkin_Wall_E_1", "pos": [-124.44999694824219, 6, -40.5]}, {"proud": 0.7, "size": [0.8999999761581421, 12, 10], "name": "COLP_CamSkin_Wall_E_2", "pos": [-124.44999694824219, 6, -26.5]}, {"proud": 1.6, "size": [1.7999999523162842, 12, 4], "name": "COLP_CamSkin_Wall_E_3", "pos": [-124, 6, -19.5]}, {"proud": 0.7, "size": [0.8999999761581421, 12, 14], "name": "COLP_CamSkin_Wall_E_4", "pos": [-124.44999694824219, 6, -8.5]}, {"proud": 0.7, "size": [0.8999999761581421, 12, 10], "name": "COLP_CamSkin_Wall_E_5", "pos": [-124.44999694824219, 6, 5.5]}, {"proud": 0.85, "size": [1.0499999523162842, 12, 2], "name": "COLP_CamSkin_Wall_E_6", "pos": [-124.375, 6, 11.5]}, {"proud": 0.7, "size": [0.8999999761581421, 12, 2], "name": "COLP_CamSkin_Wall_E_7", "pos": [-124.44999694824219, 6, 13.5]}, {"proud": 0.7, "size": [0.8999999761581421, 12, 14], "name": "COLP_CamSkin_Wall_E_8", "pos": [-124.44999694824219, 6, 23.5]}, {"proud": 1.6, "size": [1.7999999523162842, 12, 4], "name": "COLP_CamSkin_Wall_E_9", "pos": [-124, 6, 34.5]}, {"proud": 0.7, "size": [0.8999999761581421, 12, 26], "name": "COLP_CamSkin_Wall_E_10", "pos": [-124.44999694824219, 6, 49.5]}, {"proud": 0.35, "size": [0.550000011920929, 12, 2], "name": "COLP_CamSkin_Wall_E_11", "pos": [-124.625, 6, 63.5]}, {"proud": 0.55, "size": [2, 12, 0.75], "name": "COLP_CamSkin_Wall_N_E_1", "pos": [-123.69999694824219, 6, 64.32499694824219]}, {"proud": 0.3, "size": [16, 12, 0.5], "name": "COLP_CamSkin_Wall_N_E_2", "pos": [-108.69999694824219, 6, 64.44999694824219]}, {"proud": 0.15, "size": [2, 12, 0.3499999940395355], "name": "COLP_CamSkin_Wall_N_E_3", "pos": [-99.69999694824219, 6, 64.5250015258789]}, {"proud": 0.8, "size": [2, 12, 1], "name": "COLP_CamSkin_Wall_N_E_4", "pos": [-93.69999694824219, 6, 64.19999694824219]}, {"proud": 0.45, "size": [0.5, 12, 0.6499999761581421], "name": "COLP_CamSkin_Wall_N_E_5", "pos": [-92.44999694824219, 6, 64.375]}, {"p