local model = workspace:FindFirstChild("Warehouse")
if not (model and model:FindFirstChild("CollisionProxies")) then
	local src = game:GetService("ServerStorage"):FindFirstChild("_DuelSource")
	model = src and src:FindFirstChild("Warehouse") and src.Warehouse:FindFirstChild("Warehouse")
end
if not model then return "no Warehouse map model (Workspace.Warehouse or ServerStorage._DuelSource.Warehouse.Warehouse)" end
local old = model:FindFirstChild("CamSkin")
if old then old:Destroy() end
if UNDO then return "removed " .. model:GetFullName() .. ".CamSkin" end
local template = model.CollisionProxies:FindFirstChild("COLP_Wall_W")
local folder = Instance.new("Folder")
folder.Name = "CamSkin"
local n = 0
for _, e in HS:JSONDecode(DATA) do
	local p = template:Clone()
	p:ClearAllChildren()
	for k in p:GetAttributes() do p:SetAttribute(k, nil) end
	p.Name = e.name
	p.Size = Vector3.new(e.size[1], e.size[2], e.size[3])
	p.CFrame = CFrame.new(e.pos[1], e.pos[2], e.pos[3])
	p.Anchored, p.CanCollide, p.CanQuery, p.CanTouch = true, true, true, true
	p.Transparency, p.CastShadow = 1, false
	p:SetAttribute("CamSkinProud", e.proud)
	p.Parent = folder
	n += 1
end
folder.Parent = model
return ("%s.CamSkin: %d parts"):format(model:GetFullName(), n)
